--
-- Name: fence_deleting_registry(); Type: FUNCTION; Schema: webdock_admin; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_admin.fence_deleting_registry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_admin'
    AS $$
DECLARE target text; held record; supplied text;
BEGIN
 IF session_user NOT IN ('webdock_registry_runtime','webdock_admin_runtime','webdock_auth_runtime') THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='projects' THEN target:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
 ELSE target:=CASE WHEN TG_OP='DELETE' THEN OLD.project_id ELSE NEW.project_id END; END IF;
 FOR held IN SELECT j.project_id,j.claim_token,j.lease_until FROM webdock_admin.project_deletion j WHERE j.status<>'deleted' AND
  (j.project_id=target OR (TG_TABLE_NAME='vercel_project_link' AND TG_OP<>'DELETE' AND to_jsonb(NEW)->>'team_id'=j.plan->>'teamID' AND to_jsonb(NEW)->>'vercel_project_id'=j.plan->>'providerProjectID') OR (TG_TABLE_NAME='cms_instances' AND TG_OP<>'DELETE' AND EXISTS(
    SELECT 1 FROM webdock_admin.cms_instances old_instance WHERE old_instance.project_id=j.project_id AND
    (to_jsonb(NEW)->>'schema_name'=old_instance.schema_name OR to_jsonb(NEW)->>'provider_project_i_d'=old_instance.provider_project_i_d OR to_jsonb(NEW)->>'admin_u_r_l'=old_instance.admin_u_r_l)
  )))
 LOOP
  supplied:=current_setting('webdock.deletion_token',true);
  IF supplied IS DISTINCT FROM held.claim_token::text OR held.lease_until IS NULL OR held.lease_until<=statement_timestamp() OR NOT webdock_rls.operator() THEN
   RAISE EXCEPTION 'Project deletion is in progress; registry changes are fenced' USING ERRCODE='55000';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


ALTER FUNCTION webdock_admin.fence_deleting_registry() OWNER TO webdock_platform_owner;

--
-- Name: lock_hosting_project(character varying); Type: FUNCTION; Schema: webdock_admin; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_admin.lock_hosting_project(p_project_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT webdock_rls.project_allowed(p_project_id) AND NOT webdock_rls.worker(ARRAY['git-worker','database-gateway']) AND NOT webdock_rls.agent_project(p_project_id) THEN
  RAISE EXCEPTION 'Project authorization required' USING ERRCODE='42501';
 END IF;
 PERFORM id FROM webdock_admin.projects WHERE id=p_project_id FOR SHARE;
END $$;


ALTER FUNCTION webdock_admin.lock_hosting_project(p_project_id character varying) OWNER TO webdock_platform_owner;

--
-- Name: next_snowflake(); Type: FUNCTION; Schema: webdock_admin; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_admin.next_snowflake() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE wall_ms bigint; next_ms bigint; last_value bigint; counter integer;
BEGIN
 wall_ms := floor(extract(epoch FROM clock_timestamp())*1000)::bigint - 1767225600000;
 SELECT last_ms, sequence INTO last_value, counter FROM webdock_admin.snowflake_state WHERE singleton FOR UPDATE;
 next_ms := greatest(wall_ms,last_value);
 IF next_ms > last_value THEN counter := 0;
 ELSIF counter = 4095 THEN next_ms := next_ms+1; counter := 0;
 ELSE counter := counter+1;
 END IF;
 IF next_ms-wall_ms > 5000 THEN RAISE EXCEPTION 'Snowflake clock drift exceeds five seconds' USING ERRCODE='54000'; END IF;
 IF next_ms < 0 OR next_ms >= 2199023255552 THEN RAISE EXCEPTION 'Snowflake epoch range exceeded' USING ERRCODE='54000'; END IF;
 UPDATE webdock_admin.snowflake_state SET last_ms=next_ms, sequence=counter WHERE singleton;
 RETURN ((next_ms << 22) | (0::bigint << 12) | counter::bigint)::text;
END;
$$;


ALTER FUNCTION webdock_admin.next_snowflake() OWNER TO webdock_platform_owner;

