--
-- Name: database_immutable_terms(); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.database_immutable_terms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='hosting_database_plan' THEN
  IF NEW.plan IS DISTINCT FROM OLD.plan THEN RAISE EXCEPTION 'Database plan revisions are immutable'; END IF;
 ELSIF TG_TABLE_NAME='hosting_database_offer' THEN
  RAISE EXCEPTION 'Database offers are immutable';
 ELSE
  IF OLD.database_id IS NOT NULL AND NEW.database_id IS DISTINCT FROM OLD.database_id THEN RAISE EXCEPTION 'Database order is already consumed'; END IF;
  IF (NEW.offer_id,NEW.customer_id,NEW.project_id,NEW.plan_revision_id,NEW.accepted_by,NEW.accepted_at,NEW.snapshot)
     IS DISTINCT FROM (OLD.offer_id,OLD.customer_id,OLD.project_id,OLD.plan_revision_id,OLD.accepted_by,OLD.accepted_at,OLD.snapshot)
  THEN RAISE EXCEPTION 'Accepted database terms are immutable'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION webdock_auth.database_immutable_terms() OWNER TO webdock_platform_owner;

--
-- Name: guard_clerk_identity_binding(); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.guard_clerk_identity_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF ROW(NEW.issuer,NEW.external_subject,NEW.local_subject) IS DISTINCT FROM ROW(OLD.issuer,OLD.external_subject,OLD.local_subject)
 OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL) THEN
  RAISE EXCEPTION 'Clerk identity bindings cannot be reassigned or revived' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION webdock_auth.guard_clerk_identity_binding() OWNER TO webdock_platform_owner;

--
-- Name: guard_customer_owner(); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.guard_customer_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'webdock_auth'
    AS $$
DECLARE org text;
BEGIN
 IF TG_TABLE_NAME='member' THEN
  IF OLD.role<>'owner' THEN RETURN coalesce(NEW,OLD); END IF;
  IF TG_OP='UPDATE' AND NEW.role='owner' AND NEW."userId"=OLD."userId" AND NEW."organizationId"=OLD."organizationId" THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM webdock_auth."user" WHERE id=OLD."userId" AND role='user' AND NOT coalesce(banned,false) AND "emailVerified" AND NOT "mustChangePassword") THEN RETURN coalesce(NEW,OLD); END IF;
  org:=OLD."organizationId";
  PERFORM 1 FROM webdock_auth.organization o JOIN webdock_auth.tenant_customer t ON t.organization_id=o.id WHERE o.id=org FOR UPDATE OF o;
  IF FOUND AND NOT EXISTS(SELECT 1 FROM webdock_auth.member m JOIN webdock_auth."user" u ON u.id=m."userId" WHERE m."organizationId"=org AND m.id<>OLD.id AND m.role='owner' AND u.role='user' AND NOT coalesce(u.banned,false) AND u."emailVerified" AND NOT u."mustChangePassword") THEN
   RAISE EXCEPTION 'Keep at least one active verified customer owner.' USING ERRCODE='23514';
  END IF;
 ELSE
  IF OLD.role<>'user' OR coalesce(OLD.banned,false) OR NOT OLD."emailVerified" OR OLD."mustChangePassword" THEN RETURN coalesce(NEW,OLD); END IF;
  IF TG_OP='UPDATE' AND NEW.role='user' AND NOT coalesce(NEW.banned,false) AND NEW."emailVerified" AND NOT NEW."mustChangePassword" THEN RETURN NEW; END IF;
  FOR org IN SELECT o.id FROM webdock_auth.organization o JOIN webdock_auth.tenant_customer t ON t.organization_id=o.id JOIN webdock_auth.member m ON m."organizationId"=o.id WHERE m."userId"=OLD.id AND m.role='owner' ORDER BY o.id FOR UPDATE OF o LOOP
   IF NOT EXISTS(SELECT 1 FROM webdock_auth.member m JOIN webdock_auth."user" u ON u.id=m."userId" WHERE m."organizationId"=org AND m."userId"<>OLD.id AND m.role='owner' AND u.role='user' AND NOT coalesce(u.banned,false) AND u."emailVerified" AND NOT u."mustChangePassword") THEN
    RAISE EXCEPTION 'Keep at least one active verified customer owner.' USING ERRCODE='23514';
   END IF;
  END LOOP;
 END IF;
 RETURN coalesce(NEW,OLD);
END;
$$;


ALTER FUNCTION webdock_auth.guard_customer_owner() OWNER TO webdock_platform_owner;

--
-- Name: guard_paid_base(); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.guard_paid_base() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE customer text;locked boolean; previous webdock_auth.tenant_subscription;
BEGIN
 customer:=CASE WHEN TG_OP='DELETE' THEN OLD.customer_id ELSE NEW.customer_id END;
 IF pg_has_role(session_user,'webdock_platform_owner','USAGE') OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=session_user AND rolsuper) OR (webdock_rls.worker(ARRAY['polar:live:customer']) AND webdock_rls.request_scope()->>'customerID'=customer) THEN
  IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND NEW.customer_id IS DISTINCT FROM OLD.customer_id THEN RAISE EXCEPTION 'Subscription customer cannot change' USING ERRCODE='55000';END IF;
 IF TG_OP='INSERT' THEN SELECT * INTO previous FROM webdock_auth.tenant_subscription WHERE customer_id=customer;END IF;
 SELECT EXISTS(SELECT 1 FROM webdock_auth.billing_contract c WHERE c.environment='live' AND c.customer_id=customer AND c.projected_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM webdock_auth.billing_manual_release r WHERE r.contract_id=c.id)) INTO locked;
 IF locked AND (TG_OP='DELETE' OR (TG_OP='INSERT' AND (previous.base,previous.plan_id,previous.name,previous.description) IS DISTINCT FROM (NEW.base,NEW.plan_id,NEW.name,NEW.description)) OR (TG_OP='UPDATE' AND (OLD.base,OLD.plan_id,OLD.name,OLD.description) IS DISTINCT FROM (NEW.base,NEW.plan_id,NEW.name,NEW.description))) THEN RAISE EXCEPTION 'Paid base requires an explicit manual release' USING ERRCODE='55000';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;


ALTER FUNCTION webdock_auth.guard_paid_base() OWNER TO webdock_platform_owner;

