--
-- Name: publish_plugin_template(text); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.publish_plugin_template(provisioning_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p record; s jsonb; tenant_id text; existing record;
BEGIN
 IF NOT webdock_rls.plugin_provisioning_live(provisioning_id) THEN RAISE EXCEPTION 'Provisioning authority changed' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT p FROM webdock_auth.hosting_plugin_provisioning WHERE id=provisioning_id FOR UPDATE;
 s:=p.template_state;
 IF p.template_id<>'managed-cms' OR s->'migration'->>'status' IS DISTINCT FROM 'succeeded' OR s->'publication'->>'status' IS DISTINCT FROM 'succeeded'
 OR COALESCE(s->>'oauthSecretHash','') !~ '^[A-Za-z0-9_-]{43}$' OR COALESCE(s->>'instanceID','') !~ '^[1-9][0-9]{0,18}$' OR COALESCE(s->>'clientID','') !~ '^[1-9][0-9]{0,18}$'
 OR s->>'origin' IS DISTINCT FROM 'https://'||(s->>'instanceID')||'.'||(s->'approval'->>'domain')
 OR s->'publication'->'proof'->>'instanceID' IS DISTINCT FROM s->>'instanceID'
 OR s->'publication'->'proof'->>'origin' IS DISTINCT FROM s->>'origin'
 THEN RAISE EXCEPTION 'Verified instance publication required'; END IF;
 SELECT organization_id INTO STRICT tenant_id FROM webdock_auth.tenant_customer WHERE customer_id=p.customer_id;
 SELECT b.*,c."redirectUris",c.metadata INTO existing FROM webdock_auth.app_binding b JOIN webdock_auth."oauthClient" c ON c."clientId"=b.client_id WHERE b.id=s->>'instanceID';
 IF FOUND THEN
  IF existing.client_id IS DISTINCT FROM s->>'clientID' OR existing.organization_id IS DISTINCT FROM tenant_id
   OR existing."redirectUris" IS DISTINCT FROM jsonb_build_array((s->>'origin')||'/api/sso/callback')
   OR existing.metadata->>'webdock_provisioning' IS DISTINCT FROM p.id::text THEN RAISE EXCEPTION 'Website binding ownership changed'; END IF;
  RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM webdock_auth."oauthClient" WHERE "redirectUris" @> jsonb_build_array((s->>'origin')||'/api/sso/callback')) THEN RAISE EXCEPTION 'Origin already registered'; END IF;
 INSERT INTO webdock_auth."oauthClient"("clientId","clientSecret",name,"applicationType","redirectUris","postLogoutRedirectUris",scopes,"grantTypes","responseTypes","tokenEndpointAuthMethod","requirePKCE","skipConsent","enableEndSession",disabled,metadata,"createdAt","updatedAt")
 VALUES(s->>'clientID',s->>'oauthSecretHash',p.name,'web',jsonb_build_array((s->>'origin')||'/api/sso/callback'),jsonb_build_array((s->>'origin')||'/cms'),'["openid","profile","email"]','["authorization_code"]','["code"]','client_secret_post',true,true,true,false,jsonb_build_object('webdock_binding',s->>'instanceID','webdock_provisioning',p.id),now(),now());
 INSERT INTO webdock_auth.app_binding(id,client_id,label,organization_id) VALUES(s->>'instanceID',s->>'clientID',p.name,tenant_id);
END; $_$;


ALTER FUNCTION webdock_auth.publish_plugin_template(provisioning_id text) OWNER TO webdock_platform_owner;

--
-- Name: sync_customer_tenant(); Type: FUNCTION; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_auth.sync_customer_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tenant_id text;
BEGIN
 SELECT organization_id INTO tenant_id FROM webdock_auth.tenant_customer WHERE customer_id=NEW.id;
 IF tenant_id IS NULL THEN
   tenant_id := webdock_auth.next_snowflake();
   INSERT INTO webdock_auth.organization(id,name,slug,"createdAt")
   VALUES(tenant_id,NEW.name,'customer-' || NEW.id,now());
   INSERT INTO webdock_auth.tenant_customer(customer_id,organization_id) VALUES(NEW.id,tenant_id);
 ELSE
   UPDATE webdock_auth.organization SET name=NEW.name WHERE id=tenant_id;
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION webdock_auth.sync_customer_tenant() OWNER TO webdock_platform_owner;

--
-- Name: changed(); Type: FUNCTION; Schema: webdock_cache; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_cache.changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_cache'
    AS $$
BEGIN
 IF TG_OP <> 'TRUNCATE' THEN
  IF NOT EXISTS (SELECT 1 FROM changed_rows) THEN RETURN NULL; END IF;
 END IF;
 INSERT INTO webdock_cache.events(domain,transaction_id)
 VALUES(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,pg_current_xact_id()::text)
 ON CONFLICT(domain,transaction_id) DO NOTHING;
 RETURN NULL;
END $$;


ALTER FUNCTION webdock_cache.changed() OWNER TO webdock_platform_owner;

--
-- Name: prune(); Type: FUNCTION; Schema: webdock_cache; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_cache.prune() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_cache'
    AS $$
DECLARE changed integer; BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('webdock-cache-prune',0)) THEN RETURN 0; END IF;
 -- One bounded batch; removing events and rotating epochs are atomic to readers.
 WITH candidates AS (
  SELECT event_id FROM webdock_cache.events WHERE created_at<clock_timestamp()-interval '5 minutes'
  ORDER BY created_at,event_id LIMIT 10000
 ), deleted AS (
  DELETE FROM webdock_cache.events WHERE event_id IN (SELECT event_id FROM candidates) RETURNING domain
 ) UPDATE webdock_cache.domains SET epoch=gen_random_uuid() WHERE name IN(SELECT domain FROM deleted);
 GET DIAGNOSTICS changed=ROW_COUNT;
 RETURN changed;
END $$;


ALTER FUNCTION webdock_cache.prune() OWNER TO webdock_platform_owner;

--
-- Name: version(text[]); Type: FUNCTION; Schema: webdock_cache; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_cache.version(requested text[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_cache'
    AS $$
DECLARE names text[]; result text; BEGIN
 SELECT array_agg(DISTINCT name ORDER BY name) INTO names FROM unnest(requested) name;
 IF names IS NULL OR cardinality(names)>64 OR array_position(names,NULL) IS NOT NULL
 OR EXISTS(SELECT 1 FROM unnest(names) AS requested_name(name) WHERE NOT EXISTS(SELECT 1 FROM webdock_cache.domains d WHERE d.name=requested_name.name)) THEN
  RAISE EXCEPTION 'Unknown cache source';
 END IF;
 -- Never publish a view of this transaction's uncommitted source writes.
 IF EXISTS(SELECT 1 FROM webdock_cache.events e WHERE e.domain=ANY(names)
  AND e.transaction_id=pg_current_xact_id_if_assigned()::text) THEN RETURN NULL; END IF;
 -- COUNT detects a late commit whose event_id is lower than an already visible event.
 SELECT string_agg(name||':'||epoch::text||':'||events::text||':'||latest::text,'|' ORDER BY name) INTO result
 FROM (SELECT d.name,d.epoch,count(e.event_id) AS events,coalesce(max(e.event_id),0) AS latest
  FROM webdock_cache.domains d LEFT JOIN webdock_cache.events e ON e.domain=d.name
  WHERE d.name=ANY(names) GROUP BY d.name,d.epoch) versions;
 RETURN result;
END $$;


ALTER FUNCTION webdock_cache.version(requested text[]) OWNER TO webdock_platform_owner;

--
-- Name: enforce_high_water(); Type: FUNCTION; Schema: webdock_ids; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_ids.enforce_high_water() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF NEW.slot<>OLD.slot OR NEW.layout<>OLD.layout OR NEW.high_water IS NULL
    OR (OLD.high_water IS NOT NULL AND NEW.high_water<=OLD.high_water) THEN
  RAISE EXCEPTION 'Generator identity/layout and committed high-water are immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION webdock_ids.enforce_high_water() OWNER TO webdock_platform_owner;

--
-- Name: revoke_detached_member(); Type: FUNCTION; Schema: webdock_mail; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_mail.revoke_detached_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE next_revision bigint;
BEGIN
 IF TG_WHEN='BEFORE' THEN
  NEW.enabled := false;
  NEW.revision := OLD.revision + 1;
  RETURN NEW;
 END IF;
 INSERT INTO webdock_mail.configuration(customer_id) VALUES(NEW.customer_id)
 ON CONFLICT(customer_id) DO UPDATE SET revision=configuration.revision+1 RETURNING revision INTO next_revision;
 UPDATE webdock_mail.configuration_operation SET state='superseded',finished_at=now() WHERE customer_id=NEW.customer_id AND state='pending';
 INSERT INTO webdock_mail.configuration_operation(customer_id,revision,requested_by,reason) VALUES(NEW.customer_id,next_revision,NULL,'membership_revoked');
 RETURN NULL;
END $$;


ALTER FUNCTION webdock_mail.revoke_detached_member() OWNER TO webdock_platform_owner;

--
-- Name: actor(); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.actor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE s jsonb; actor_row record; preview_row record;
BEGIN
 s:=webdock_rls.request_scope();
 IF session_user NOT IN ('webdock_auth_runtime','webdock_registry_runtime') OR s->>'kind' IS DISTINCT FROM 'session' THEN RETURN NULL; END IF;

 IF s ? 'clerk' THEN
  IF jsonb_typeof(s->'clerk') IS DISTINCT FROM 'object' OR jsonb_typeof(s->'clerk'->'operator') IS DISTINCT FROM 'boolean' OR (s->'clerk'->>'expiresAt')::numeric<=extract(epoch FROM statement_timestamp())*1000
   OR (s->'clerk'->>'verifiedAt')::numeric>extract(epoch FROM statement_timestamp())*1000
   OR (s->'clerk'->>'verifiedAt')::numeric<extract(epoch FROM statement_timestamp())*1000-60000
   OR (s->'clerk'->>'expiresAt')::numeric>(s->'clerk'->>'verifiedAt')::numeric+60000
   OR s->'clerk'->>'expiresAt' IS NULL OR s->'clerk'->>'verifiedAt' IS NULL THEN RETURN NULL; END IF;
  SELECT u.id,u.email INTO actor_row FROM webdock_auth.clerk_identity i JOIN webdock_auth."user" u ON u.id=i.user_id
   WHERE i.issuer=s->'clerk'->>'issuer' AND i.clerk_user_id=s->'clerk'->>'userID' AND i.enabled AND u.id=s->>'subject'
   AND NOT coalesce(u.banned,false);
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF s->'clerk'->>'organizationID' IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM webdock_auth.clerk_organization o JOIN webdock_auth.tenant_customer t ON t.organization_id=o.organization_id JOIN webdock_admin.customers c ON c.id=t.customer_id
   WHERE o.issuer=s->'clerk'->>'issuer' AND o.clerk_organization_id=s->'clerk'->>'clerkOrganizationID' AND o.organization_id=s->'clerk'->>'organizationID'
   AND t.customer_id=s->'clerk'->>'customerID' AND o.enabled AND c.status='active' AND s->'clerk'->>'role' IN ('admin','member')) THEN RETURN NULL; END IF;
  SELECT p.session_id,p.actor_id,p.customer_id,p.organization_id,p.expires_at,p.expired_at,
   (p.expired_at IS NULL AND p.expires_at>statement_timestamp() AND c.status='active' AND t.organization_id=p.organization_id) AS valid INTO preview_row
   FROM webdock_auth.console_tenant_preview p LEFT JOIN webdock_admin.customers c ON c.id=p.customer_id LEFT JOIN webdock_auth.tenant_customer t ON t.customer_id=p.customer_id
   WHERE p.issuer=s->'clerk'->>'issuer' AND p.session_id=s->>'sessionID' AND p.actor_id=actor_row.id;
  RETURN jsonb_build_object('subject',actor_row.id,'email',actor_row.email,'sessionID',s->>'sessionID','operator',(s->'clerk'->>'operator')::boolean AND NOT FOUND,'root',(s->'clerk'->>'operator')::boolean,'clerk',s->'clerk','preview',CASE WHEN FOUND THEN to_jsonb(preview_row) ELSE NULL END);
 END IF;

 IF s->>'authProvider'='clerk' THEN
  IF jsonb_typeof(s->'memberships') IS DISTINCT FROM 'object'
   OR jsonb_typeof(s->'memberships'->'operator') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(s->'memberships'->'twoFactorEnabled') IS DISTINCT FROM 'boolean'
   OR s->'memberships'->>'subject' IS DISTINCT FROM s->>'subject' OR s->'memberships'->>'sessionID' IS DISTINCT FROM s->>'sessionID'
   OR s->'memberships'->>'expiresAt' IS NULL OR s->'memberships'->>'verifiedAt' IS NULL
   OR (s->'memberships'->>'expiresAt')::numeric<=extract(epoch FROM statement_timestamp())*1000
   OR (s->'memberships'->>'verifiedAt')::numeric NOT BETWEEN extract(epoch FROM statement_timestamp())*1000-60000 AND extract(epoch FROM statement_timestamp())*1000
   OR (s->'memberships'->>'expiresAt')::numeric>(s->'memberships'->>'verifiedAt')::numeric+60000
   OR ((s->'memberships'->>'operator')::boolean AND NOT (s->'memberships'->>'twoFactorEnabled')::boolean) THEN RETURN NULL; END IF;
  SELECT u.id,u.email INTO actor_row FROM webdock_auth.clerk_identity i JOIN webdock_auth."user" u ON u.id=i.user_id JOIN webdock_auth.session session ON session."userId"=u.id
   WHERE i.issuer=s->'memberships'->>'issuer' AND i.clerk_user_id=s->'memberships'->>'userID' AND i.enabled AND u.id=s->>'subject'
   AND session.id=s->>'sessionID' AND session."expiresAt">statement_timestamp() AND NOT coalesce(u.banned,false) AND u."emailVerified" AND NOT u."mustChangePassword";
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT p.session_id,p.actor_id,p.customer_id,p.organization_id,p.expires_at,p.expired_at, (p.expired_at IS NULL AND p.expires_at>statement_timestamp() AND c.status='active' AND t.organization_id=p.organization_id) AS valid INTO preview_row FROM webdock_auth.studio_tenant_preview p LEFT JOIN webdock_admin.customers c ON c.id=p.customer_id LEFT JOIN webdock_auth.tenant_customer t ON t.customer_id=p.customer_id WHERE p.session_id=s->>'sessionID' AND p.actor_id=actor_row.id;
  RETURN jsonb_build_object('subject',actor_row.id,'email',actor_row.email,'sessionID',s->>'sessionID','operator',(s->'memberships'->>'operator')::boolean AND NOT FOUND,'root',(s->'memberships'->>'operator')::boolean,'preview',CASE WHEN FOUND THEN to_jsonb(preview_row) ELSE NULL END);
 END IF;
 SELECT u.id,u.email,u.role,u."twoFactorEnabled" INTO actor_row FROM webdock_auth."user" u JOIN webdock_auth.session a ON a."userId"=u.id WHERE u.id=s->>'subject' AND a.id=s->>'sessionID' AND a."expiresAt">statement_timestamp() AND NOT coalesce(u.banned,false) AND u."emailVerified" AND NOT u."mustChangePassword" AND (u.role='user' OR (u.role='operator' AND u."twoFactorEnabled"));
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT p.session_id,p.actor_id,p.customer_id,p.organization_id,p.expires_at,p.expired_at, (p.expired_at IS NULL AND p.expires_at>statement_timestamp() AND c.status='active' AND t.organization_id=p.organization_id) AS valid INTO preview_row FROM webdock_auth.studio_tenant_preview p LEFT JOIN webdock_admin.customers c ON c.id=p.customer_id LEFT JOIN webdock_auth.tenant_customer t ON t.customer_id=p.customer_id WHERE p.session_id=s->>'sessionID' AND p.actor_id=actor_row.id;
 RETURN jsonb_build_object('subject',actor_row.id,'email',actor_row.email,'sessionID',s->>'sessionID','operator',actor_row.role='operator' AND NOT FOUND,'root',actor_row.role='operator','preview',CASE WHEN FOUND THEN to_jsonb(preview_row) ELSE NULL END);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN NULL;
END $$;


ALTER FUNCTION webdock_rls.actor() OWNER TO webdock_policy_owner;

