    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$ SELECT webdock_rls.worker(ARRAY['agent']) AND (EXISTS(SELECT 1 FROM webdock_auth.hosting_project p WHERE p.customer_id=customer AND p.cluster_id=webdock_rls.request_scope()->>'clusterID') OR EXISTS(SELECT 1 FROM webdock_mail.cluster_reservation r WHERE r.customer_id=customer AND r.cluster_id=webdock_rls.request_scope()->>'clusterID')) $$;


ALTER FUNCTION webdock_rls.agent_customer(customer text) OWNER TO webdock_policy_owner;

