-- Name: billing_admin(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_admin(customer text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
 SELECT webdock_rls.customer_permission(customer,'org:billing:manage',false)
$$;


ALTER FUNCTION webdock_rls.billing_admin(customer text) OWNER TO webdock_platform_owner;

--
-- Name: billing_base_locked(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_base_locked(customer text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF NOT webdock_rls.customer_permission(customer,'org:billing:manage') THEN RAISE EXCEPTION 'Customer authority required' USING ERRCODE='42501';END IF;
 RETURN EXISTS(SELECT 1 FROM webdock_auth.billing_contract c WHERE c.environment='live' AND c.customer_id=customer AND c.projected_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM webdock_auth.billing_manual_release r WHERE r.contract_id=c.id));
END $$;


ALTER FUNCTION webdock_rls.billing_base_locked(customer text) OWNER TO webdock_platform_owner;

--
-- Name: billing_catalog(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_catalog(env text, customer text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF NOT webdock_rls.billing_reader(customer) THEN RAISE EXCEPTION 'Customer billing administrator required' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT value FROM (SELECT webdock_rls.billing_version(env,v.id,customer,NULL) AS value FROM webdock_auth.billing_product_version v JOIN webdock_auth.billing_product p ON p.id=v.product_id WHERE p.visibility='public') available WHERE value IS NOT NULL;
END $$;


ALTER FUNCTION webdock_rls.billing_catalog(env text, customer text) OWNER TO webdock_platform_owner;

--
-- Name: billing_catalog_terms(text, uuid); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_catalog_terms(env text, polar uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF env NOT IN ('sandbox','live') OR NOT webdock_rls.worker(ARRAY['polar:'||env||':catalog']) THEN RAISE EXCEPTION 'Billing catalog worker required' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT jsonb_build_object('organizationID',c.organization_id,'versionID',v.id,'operationID',m.operation_id,'sku',p.sku,'hash',m.desired_hash,'name',p.name,'description',v.description,'amount',v.amount,'currency',v.currency,'taxBehavior',v.tax_behavior,'interval',v.interval,'visibility',p.visibility,'productID',m.polar_product_id)
 FROM webdock_auth.billing_product_mapping m JOIN webdock_auth.billing_product_version v ON v.id=m.version_id JOIN webdock_auth.billing_product p ON p.id=v.product_id JOIN webdock_auth.billing_connection c ON c.environment=m.environment
 WHERE m.environment=env AND m.polar_product_id IS NOT NULL AND (polar IS NULL OR m.polar_product_id=polar) AND m.status<>'archived' ORDER BY m.version_id;
END $$;


ALTER FUNCTION webdock_rls.billing_catalog_terms(env text, polar uuid) OWNER TO webdock_platform_owner;

--
-- Name: billing_checkout_job(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_checkout_job(env text, attempt text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE row webdock_auth.billing_checkout;
BEGIN
 SELECT * INTO row FROM webdock_auth.billing_checkout WHERE environment=env AND id=attempt AND state='creating';
 IF NOT FOUND OR NOT webdock_rls.billing_admin(row.customer_id) THEN RAISE EXCEPTION 'Authorized checkout required' USING ERRCODE='42501';END IF;
 INSERT INTO webdock_auth.billing_job(environment,customer_id,kind,dedupe_key,status,claim_token,lease_until)
 VALUES(env,row.customer_id,'checkout','checkout:'||row.id,'running',gen_random_uuid(),now()+interval '60 seconds') ON CONFLICT(environment,dedupe_key) DO NOTHING;
END $$;


ALTER FUNCTION webdock_rls.billing_checkout_job(env text, attempt text) OWNER TO webdock_platform_owner;

--
-- Name: billing_cms_allowed(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_cms_allowed(binding text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE enabled boolean;status text;contract text;
BEGIN
 IF session_user<>'webdock_auth_bootstrap' THEN RAISE EXCEPTION 'Identity service required' USING ERRCODE='42501';END IF;
 SELECT enforcement_enabled INTO enabled FROM webdock_auth.billing_connection WHERE environment='live';IF NOT coalesce(enabled,false) THEN RETURN true;END IF;
 SELECT id,service_status INTO contract,status FROM webdock_auth.billing_contract WHERE environment='live' AND binding_id=binding AND projected_at IS NOT NULL ORDER BY accepted_at DESC,id DESC LIMIT 1;
 RETURN status IS NULL OR status IN ('active','warning') OR EXISTS(SELECT 1 FROM webdock_auth.billing_manual_release WHERE contract_id=contract);
END $$;


ALTER FUNCTION webdock_rls.billing_cms_allowed(binding text) OWNER TO webdock_platform_owner;

--
-- Name: billing_customer_lookup(text, text, uuid); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_customer_lookup(env text, external text, polar uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE customer text;
BEGIN
 IF env NOT IN ('sandbox','live') OR NOT webdock_rls.worker(ARRAY['polar:'||env||':dispatcher']) THEN RAISE EXCEPTION 'Billing dispatcher required' USING ERRCODE='42501';END IF;
 SELECT customer_id INTO customer FROM webdock_auth.billing_customer WHERE environment=env AND external_id=external AND (polar_customer_id IS NULL OR polar_customer_id=polar) AND (env='live' OR is_test);
 RETURN customer;
END $$;


ALTER FUNCTION webdock_rls.billing_customer_lookup(env text, external text, polar uuid) OWNER TO webdock_platform_owner;

--
-- Name: billing_due_customers(text, text, integer); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_due_customers(env text, after_customer text DEFAULT ''::text, page_limit integer DEFAULT 100) RETURNS TABLE(customer_id text, interval_minutes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF env NOT IN ('sandbox','live') OR page_limit<1 OR page_limit>100 OR NOT webdock_rls.worker(ARRAY['polar:'||env||':dispatcher']) THEN RAISE EXCEPTION 'Billing dispatcher required' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT c.customer_id::text,CASE WHEN EXISTS(SELECT 1 FROM webdock_auth.billing_contract b WHERE b.environment=env AND b.customer_id=c.customer_id AND b.state IN ('pending','needs_review','paid_needs_review')) OR EXISTS(SELECT 1 FROM webdock_auth.billing_subscription s WHERE s.environment=env AND s.customer_id=c.customer_id AND s.status IN ('past_due','incomplete')) THEN 15 ELSE 360 END
 FROM webdock_auth.billing_customer c WHERE c.environment=env AND c.customer_id::text>after_customer AND (env='live' OR c.is_test) AND EXISTS(SELECT 1 FROM webdock_auth.billing_contract b WHERE b.environment=env AND b.customer_id=c.customer_id AND b.state<>'ended') ORDER BY c.customer_id::text LIMIT page_limit;
END $$;


ALTER FUNCTION webdock_rls.billing_due_customers(env text, after_customer text, page_limit integer) OWNER TO webdock_platform_owner;

--
-- Name: billing_reader(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_reader(customer text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
 SELECT webdock_rls.billing_admin(customer) OR coalesce(webdock_rls.actor() IS NOT NULL AND webdock_rls.actor()->'preview'='null'::jsonb AND EXISTS(SELECT 1 FROM webdock_auth.tenant_customer t JOIN webdock_admin.customers c ON c.id=t.customer_id WHERE t.customer_id=customer AND c.status='active' AND webdock_rls.membership_role(t.organization_id) IN ('owner','admin')),false)
$$;


ALTER FUNCTION webdock_rls.billing_reader(customer text) OWNER TO webdock_platform_owner;

--
-- Name: billing_sale_config(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_sale_config(env text, customer text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE result jsonb;
BEGIN
 IF env NOT IN ('sandbox','live') OR NOT webdock_rls.billing_reader(customer) THEN RAISE EXCEPTION 'Customer billing administrator required' USING ERRCODE='42501';END IF;
 IF env='sandbox' AND NOT EXISTS(SELECT 1 FROM webdock_auth.billing_customer WHERE environment=env AND customer_id=customer AND is_test) THEN RAISE EXCEPTION 'Explicit sandbox customer required' USING ERRCODE='42501';END IF;
 SELECT jsonb_build_object('organizationID',organization_id,'salesEnabled',sales_enabled,'endpointID',endpoint_id) INTO result FROM webdock_auth.billing_connection WHERE environment=env;
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.billing_sale_config(env text, customer text) OWNER TO webdock_platform_owner;

--
-- Name: billing_secret(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_secret(env text, kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE row webdock_auth.billing_connection;
BEGIN
 IF env NOT IN ('sandbox','live') OR kind NOT IN ('token','webhook') THEN RAISE EXCEPTION 'Invalid billing credential request' USING ERRCODE='42501';END IF;
 IF kind='webhook' THEN
  IF NOT webdock_rls.worker(ARRAY['polar:'||env||':inbox']) THEN RAISE EXCEPTION 'Inbox authority required' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT webdock_rls.worker(ARRAY['polar:'||env||':catalog','polar:'||env||':customer','polar:'||env||':dispatcher']) THEN RAISE EXCEPTION 'Billing worker authority required' USING ERRCODE='42501';END IF;
 END IF;
 SELECT * INTO row FROM webdock_auth.billing_connection WHERE environment=env;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF kind='token' THEN RETURN jsonb_build_object('encrypted',row.encrypted_token,'version',row.token_version,'organizationID',row.organization_id);END IF;
 RETURN jsonb_build_object('encrypted',row.encrypted_webhook_secret,'version',row.webhook_version,'previous',CASE WHEN row.previous_webhook_until>now() THEN row.previous_webhook_secret END,'previousVersion',row.previous_webhook_version);
END $$;


ALTER FUNCTION webdock_rls.billing_secret(env text, kind text) OWNER TO webdock_platform_owner;

--
-- Name: billing_site(text, text, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_site(customer text, project text, binding text, management_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE result jsonb;
BEGIN
 IF NOT webdock_rls.billing_reader(customer) THEN RAISE EXCEPTION 'Customer billing administrator required' USING ERRCODE='42501';END IF;
 SELECT jsonb_build_object('organizationID',b.organization_id,'bindingID',b.id,'projectID',p.id,'name',p.name) INTO result
 FROM webdock_auth.app_binding b JOIN webdock_auth."oauthClient" client ON client."clientId"=b.client_id AND NOT coalesce(client.disabled,false)
 JOIN webdock_auth.tenant_customer t ON t.organization_id=b.organization_id JOIN webdock_admin.projects p ON p.customer_id=t.customer_id JOIN webdock_admin.cms_instances i ON i.project_id=p.id
 WHERE t.customer_id=customer AND p.id=project AND b.id=binding AND b.enabled AND p.status='active' AND i.status='active' AND i.admin_u_r_l=management_url
 AND NOT EXISTS(SELECT 1 FROM webdock_admin.project_deletion WHERE project_id=p.id);
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.billing_site(customer text, project text, binding text, management_url text) OWNER TO webdock_platform_owner;

--
-- Name: billing_sites(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_sites(customer text, studio text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF NOT webdock_rls.billing_reader(customer) THEN RAISE EXCEPTION 'Customer billing administrator required' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT jsonb_build_object('bindingID',b.id,'projectID',p.id,'name',p.name) FROM webdock_auth.app_binding b
 JOIN webdock_auth."oauthClient" client ON client."clientId"=b.client_id AND NOT coalesce(client.disabled,false)
 JOIN webdock_auth.tenant_customer t ON t.organization_id=b.organization_id JOIN webdock_admin.projects p ON p.customer_id=t.customer_id JOIN webdock_admin.cms_instances i ON i.project_id=p.id
 WHERE t.customer_id=customer AND b.enabled AND p.status='active' AND i.status='active' AND i.admin_u_r_l=studio||'/sites/'||b.id AND NOT EXISTS(SELECT 1 FROM webdock_admin.project_deletion WHERE project_id=p.id) ORDER BY p.name,p.id;
END $$;


ALTER FUNCTION webdock_rls.billing_sites(customer text, studio text) OWNER TO webdock_platform_owner;

--
-- Name: billing_version(text, text, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.billing_version(env text, version text, customer text, offer text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE result jsonb;
BEGIN
 IF env NOT IN ('sandbox','live') OR NOT webdock_rls.billing_reader(customer) THEN RAISE EXCEPTION 'Customer billing administrator required' USING ERRCODE='42501';END IF;
 IF env='sandbox' AND NOT EXISTS(SELECT 1 FROM webdock_auth.billing_customer WHERE environment=env AND customer_id=customer AND is_test) THEN RAISE EXCEPTION 'Explicit sandbox customer required' USING ERRCODE='42501';END IF;
 SELECT jsonb_build_object('versionID',v.id,'productID',m.polar_product_id,'priceIDs',m.price_ids,'name',p.name,'description',v.description,'terms',v.terms_text,'amount',v.amount::text,'currency',v.currency,'taxBehavior',v.tax_behavior,'interval',v.interval,'entitlements',v.entitlements,'termsHash',v.terms_hash) INTO result
 FROM webdock_auth.billing_product_version v JOIN webdock_auth.billing_product p ON p.id=v.product_id JOIN webdock_auth.billing_product_mapping m ON m.version_id=v.id AND m.environment=env
 WHERE v.id=billing_version.version AND v.frozen AND v.terms_text<>'' AND m.status='ready' AND m.polar_product_id IS NOT NULL AND p.operationally_ready AND NOT p.archived AND p.family='website'
 AND (p.visibility<>'public' OR v.version=(SELECT max(newest.version) FROM webdock_auth.billing_product_version newest JOIN webdock_auth.billing_product_mapping published ON published.version_id=newest.id AND published.environment=env AND published.status='ready' WHERE newest.product_id=p.id))
 AND (p.visibility='public' OR EXISTS(SELECT 1 FROM webdock_auth.billing_offer o WHERE o.id=offer AND o.environment=env AND o.customer_id=customer AND o.version_id=v.id));
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.billing_version(env text, version text, customer text, offer text) OWNER TO webdock_platform_owner;

--
-- Name: binding_database_status(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.binding_database_status(binding text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 RETURN (SELECT jsonb_build_object('state',d.state,'credential_revision',d.credential_revision,'confirmed_credential_revision',d.confirmed_credential_revision,'ca_certificate',b.ca_certificate,'endpoint_ready',b.endpoint_ready)
 FROM webdock_auth.hosting_service_binding s JOIN webdock_auth.hosting_database d ON d.id=s.service->>'databaseID' AND d.project_id=s.project_id AND d.customer_id=s.customer_id JOIN webdock_auth.hosting_database_backend b ON b.id=d.backend_id
 WHERE s.id=binding AND (webdock_rls.customer_allowed(s.customer_id::text) OR webdock_rls.worker(ARRAY['git-worker']) OR webdock_rls.agent_project(s.project_id::text)));
END $$;


ALTER FUNCTION webdock_rls.binding_database_status(binding text) OWNER TO webdock_platform_owner;

--
-- Name: binding_mail_ready(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.binding_mail_ready(binding text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 RETURN EXISTS(SELECT 1 FROM webdock_auth.hosting_service_binding b JOIN webdock_auth.mail_api_key k ON k.id=b.mail_key_id AND k.customer_id=b.customer_id JOIN webdock_auth.mail_connection c ON c.id=k.connection_id AND c.customer_id=b.customer_id JOIN webdock_auth.mail_sender_domain d ON d.id=k.domain_id AND d.customer_id=b.customer_id CROSS JOIN webdock_auth.platform_settings p WHERE b.id=binding AND k.revoked_at IS NULL AND c.state='ready' AND c.deleted_at IS NULL AND d.status='ownership_verified' AND d.deleted_at IS NULL AND p.id=true AND p.settings->>'mailGatewayEnabled'='true' AND (c.kind<>'platform' OR p.settings->>'mailEnabled'='true') AND (webdock_rls.customer_allowed(b.customer_id::text) OR webdock_rls.worker(ARRAY['git-worker']) OR webdock_rls.agent_project(b.project_id::text)));
END $$;


ALTER FUNCTION webdock_rls.binding_mail_ready(binding text) OWNER TO webdock_platform_owner;

--
-- Name: cancel_obsolete_git_builds(); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.cancel_obsolete_git_builds() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE cancelled record;
BEGIN
 FOR cancelled IN
  UPDATE webdock_auth.git_build b SET status='cancelled',generation=b.generation+1,lease_until=NULL,finished_at=now(),failure_code='SOURCE_CHANGED'
  FROM webdock_auth.git_source s JOIN webdock_auth.git_connection c ON c.id=s.connection_id
  WHERE b.source_id=s.id AND b.status IN ('queued','running')
   AND (webdock_rls.worker(ARRAY['git-worker']) OR webdock_rls.customer_permission(b.customer_id,'org:projects:manage') OR webdock_rls.customer_permission(b.customer_id,'org:deployments:create'))
   AND (NOT s.enabled OR c.state<>'active' OR s.revision<>b.source_revision OR c.generation<>b.connection_generation) RETURNING b.id
 LOOP
  INSERT INTO webdock_auth.git_check_outbox(build_id,installation_id,repository_id,source_sha,status,conclusion)
  SELECT b.id,c.installation_id,s.repository_id,b.source_sha,'completed','cancelled' FROM webdock_auth.git_build b JOIN webdock_auth.git_source s ON s.id=b.source_id JOIN webdock_auth.git_connection c ON c.id=s.connection_id WHERE b.id=cancelled.id
  ON CONFLICT(build_id) DO UPDATE SET status='completed',conclusion='cancelled',version=webdock_auth.git_check_outbox.version+1,retry_at=now();
 END LOOP;
 UPDATE webdock_auth.git_release r SET status='superseded',revision=r.revision+1 FROM webdock_auth.git_source s JOIN webdock_auth.git_connection c ON c.id=s.connection_id
 WHERE r.source_id=s.id AND r.status IN ('awaiting-approval','queued')
  AND (webdock_rls.worker(ARRAY['git-worker']) OR webdock_rls.customer_permission(r.customer_id,'org:projects:manage') OR webdock_rls.customer_permission(r.customer_id,'org:deployments:create'))
  AND (NOT s.enabled OR c.state<>'active' OR s.revision<>r.source_revision OR c.generation<>r.connection_generation);
END $$;


ALTER FUNCTION webdock_rls.cancel_obsolete_git_builds() OWNER TO webdock_platform_owner;

--
-- Name: capacity_cluster_allowed(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.capacity_cluster_allowed(cluster_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE scope jsonb; cluster record;
BEGIN
 scope:=webdock_rls.request_scope();
 IF scope IS NULL OR cluster_id IS NULL THEN RETURN false; END IF;
 SELECT c.ownership,c.dedicated_customer_id INTO cluster FROM webdock_auth.hosting_cluster c WHERE c.id=capacity_cluster_allowed.cluster_id;
 IF NOT FOUND THEN RETURN false; END IF;
 IF scope->>'kind'='system' AND session_user='webdock_worker_runtime' THEN
  IF scope->>'clusterID' IS NOT NULL AND scope->>'clusterID'<>cluster_id THEN RETURN false; END IF;
  -- The authenticated build dispatcher publishes to both platform and BYOK clusters.
  IF scope->>'purpose'='hosting-setup' THEN RETURN webdock_rls.setup_cluster(cluster_id); END IF;
  IF scope->>'purpose'='git-worker' THEN RETURN true; END IF;
  IF scope->>'purpose'='agent' THEN RETURN coalesce(scope->>'clusterID'=cluster_id,false); END IF;
  IF scope->>'purpose'='database-order' THEN
   RETURN coalesce(scope->>'customerID' IS NOT NULL AND webdock_rls.customer_allowed(scope->>'customerID') AND
    (cluster.ownership='platform' OR (cluster.ownership='tenant' AND cluster.dedicated_customer_id=scope->>'customerID')),false);
  END IF;
  RETURN false;
 END IF;
 IF scope->>'kind' IS DISTINCT FROM 'session' OR session_user<>'webdock_auth_runtime' OR webdock_rls.actor() IS NULL THEN RETURN false; END IF;
 RETURN coalesce(webdock_rls.operator() OR cluster.ownership='platform' OR
  (cluster.ownership='tenant' AND webdock_rls.customer_allowed(cluster.dedicated_customer_id)),false);
END $$;


ALTER FUNCTION webdock_rls.capacity_cluster_allowed(cluster_id text) OWNER TO webdock_platform_owner;

--
-- Name: capacity_demand(text, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.capacity_demand(cluster_id text, demand_kind text, excluded_customer text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb; reserved_volume numeric; approved numeric; observed numeric; has_pools boolean;
BEGIN
 IF webdock_rls.capacity_cluster_allowed(cluster_id) IS NOT TRUE OR demand_kind IS NULL OR demand_kind NOT IN ('apps','native','all') THEN RAISE EXCEPTION 'Capacity authorization required' USING ERRCODE='42501'; END IF;
 IF excluded_customer IS NOT NULL AND webdock_rls.customer_allowed(excluded_customer) IS NOT TRUE THEN RAISE EXCEPTION 'Capacity exclusion denied' USING ERRCODE='42501'; END IF;
 SELECT COALESCE(sum(p.capacity_bytes),0),count(*)>0 INTO reserved_volume,has_pools FROM webdock_auth.hosting_database_pool p WHERE p.cluster_id=capacity_demand.cluster_id;
 SELECT reserved_volume+COALESCE(sum((b.demand->>'volumeBytes')::numeric),0) INTO reserved_volume FROM webdock_auth.hosting_database_backend b WHERE b.cluster_id=capacity_demand.cluster_id AND b.state<>'purged' AND NOT EXISTS(SELECT 1 FROM webdock_auth.hosting_database_pool p WHERE p.cluster_id=b.cluster_id AND p.pool_id=b.pool_id);
 SELECT (c.capacity->>'volumeBytes')::numeric,(a.observation->'capacity'->>'volumeBytes')::numeric,
 has_pools OR EXISTS(SELECT 1 FROM webdock_auth.hosting_database_backend b WHERE b.cluster_id=c.id AND b.state<>'purged') OR a.observation->'capabilities'->>'databaseVersion'='1'
 INTO approved,observed,has_pools FROM webdock_auth.hosting_cluster c LEFT JOIN webdock_auth.hosting_agent a ON a.cluster_id=c.id WHERE c.id=capacity_demand.cluster_id;
 IF has_pools AND approved IS NOT NULL AND observed IS NOT NULL THEN reserved_volume=greatest(reserved_volume,approved-observed); END IF;
 WITH reservations AS (
  SELECT r.demand,r.status FROM webdock_auth.hosting_reservation r WHERE r.cluster_id=capacity_demand.cluster_id AND r.status<>'released' AND demand_kind IN ('apps','all')
  UNION ALL SELECT r.demand,r.status FROM webdock_mail.cluster_reservation r WHERE r.cluster_id=capacity_demand.cluster_id AND (excluded_customer IS NULL OR r.customer_id<>excluded_customer) AND demand_kind IN ('native','all')
  UNION ALL SELECT b.demand||jsonb_build_object('volumeBytes',0),CASE WHEN b.state IN ('provisioning','updating') THEN 'reserved' ELSE 'active' END FROM webdock_auth.hosting_database_backend b WHERE b.cluster_id=capacity_demand.cluster_id AND b.state<>'purged' AND demand_kind IN ('native','all')
  UNION ALL SELECT jsonb_build_object('volumeBytes',reserved_volume),'active' WHERE demand_kind IN ('native','all')
 ), dimensions AS (SELECT unnest(ARRAY['apps','cpuMillicores','memoryBytes','volumeBytes','ephemeralBytes','replicasPerApp','concurrentDeployments']) AS key),
 amounts AS (SELECT d.key,CASE WHEN d.key='concurrentDeployments' AND r.status='active' THEN 0 ELSE COALESCE((r.demand->>d.key)::numeric,0) END AS value FROM dimensions d LEFT JOIN reservations r ON true),
 totals AS (SELECT key,CASE WHEN key='replicasPerApp' THEN max(value) ELSE sum(value) END AS value,min(value) AS minimum,bool_and(value=trunc(value)) AS integral FROM amounts GROUP BY key)
 SELECT jsonb_object_agg(key,value) INTO result FROM totals WHERE integral AND minimum>=0 AND value BETWEEN 0 AND 9007199254740991 AND value=trunc(value);
 IF (SELECT count(*) FROM jsonb_object_keys(result))<>7 THEN RAISE EXCEPTION 'Invalid cluster reservation'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.capacity_demand(cluster_id text, demand_kind text, excluded_customer text) OWNER TO webdock_platform_owner;

--
-- Name: capacity_pools(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.capacity_pools(cluster_id text) RETURNS TABLE(node text, pool_id text, capacity_bytes text, held_cpu numeric, held_memory numeric, held_volume numeric, known_cpu numeric, known_memory numeric, allocated numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF webdock_rls.capacity_cluster_allowed(cluster_id) IS NOT TRUE THEN RAISE EXCEPTION 'Capacity authorization required' USING ERRCODE='42501'; END IF;
 RETURN QUERY WITH physical AS (SELECT b.id,b.node,b.pool_id,b.demand FROM webdock_auth.hosting_database_backend b WHERE b.cluster_id=capacity_pools.cluster_id AND b.state<>'purged'),
 pools AS (SELECT p.node,p.pool_id,p.capacity_bytes,o.value AS observation FROM webdock_auth.hosting_database_pool p LEFT JOIN webdock_auth.hosting_agent a ON a.cluster_id=p.cluster_id LEFT JOIN LATERAL jsonb_array_elements(COALESCE(a.observation->'capabilities'->'databasePools','[]'::jsonb)) o ON o.value->>'node'=p.node AND o.value->>'poolID'=p.pool_id::text WHERE p.cluster_id=capacity_pools.cluster_id)
 SELECT p.node::text,p.pool_id::text,p.capacity_bytes::text,
 COALESCE((SELECT sum((b.demand->>'cpuMillicores')::numeric) FROM physical b WHERE b.node=p.node),0),
 COALESCE((SELECT sum((b.demand->>'memoryBytes')::numeric) FROM physical b WHERE b.node=p.node),0),
 COALESCE((SELECT sum((b.demand->>'volumeBytes')::numeric) FROM physical b WHERE b.node=p.node AND b.pool_id=p.pool_id),0),
 COALESCE((SELECT sum((o->>'cpuMillicores')::numeric) FROM jsonb_array_elements(COALESCE(p.observation->'observedDatabases','[]'::jsonb)) o WHERE EXISTS(SELECT 1 FROM physical b WHERE b.node=p.node AND b.id=o->>'installationID')),0),
 COALESCE((SELECT sum((o->>'memoryBytes')::numeric) FROM jsonb_array_elements(COALESCE(p.observation->'observedDatabases','[]'::jsonb)) o WHERE EXISTS(SELECT 1 FROM physical b WHERE b.node=p.node AND b.id=o->>'installationID')),0),
 COALESCE((SELECT sum((o->>'volumeBytes')::numeric) FROM jsonb_array_elements(COALESCE(p.observation->'allocations','[]'::jsonb)) o WHERE EXISTS(SELECT 1 FROM physical b WHERE b.node=p.node AND b.id=o->>'installationID')),0)
 FROM pools p;
END $$;


ALTER FUNCTION webdock_rls.capacity_pools(cluster_id text) OWNER TO webdock_platform_owner;

--
-- Name: capacity_slots(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.capacity_slots(backend_id text, excluded_database text DEFAULT NULL::text) RETURNS TABLE(count integer, bytes text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM webdock_auth.hosting_database_backend b WHERE b.id=capacity_slots.backend_id AND webdock_rls.capacity_cluster_allowed(b.cluster_id)) THEN RAISE EXCEPTION 'Capacity authorization required' USING ERRCODE='42501'; END IF;
 IF excluded_database IS NOT NULL AND NOT EXISTS(SELECT 1 FROM webdock_auth.hosting_database d WHERE d.id=excluded_database AND d.backend_id=capacity_slots.backend_id AND webdock_rls.customer_allowed(d.customer_id)) THEN RAISE EXCEPTION 'Capacity exclusion denied' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT sum(x.count)::integer,sum(x.bytes)::text FROM (
 SELECT count(*) AS count,COALESCE(sum((p.plan->>'logicalStorageAllowanceBytes')::numeric),0) AS bytes FROM webdock_auth.hosting_database d JOIN webdock_auth.hosting_database_plan p ON p.id=COALESCE(d.pending_plan_revision_id,d.plan_revision_id) WHERE d.backend_id=capacity_slots.backend_id AND d.state<>'purged' AND (excluded_database IS NULL OR d.id<>excluded_database)
 UNION ALL SELECT count(*),COALESCE(sum(m.source_allowance_bytes),0) FROM webdock_auth.hosting_database_migration m WHERE m.source_backend_id=capacity_slots.backend_id AND m.state='retained') x;
END $$;


ALTER FUNCTION webdock_rls.capacity_slots(backend_id text, excluded_database text) OWNER TO webdock_platform_owner;

--
-- Name: cluster_snapshot(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.cluster_snapshot(cluster_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c record; a record; observation_value jsonb; pools jsonb;
BEGIN
 IF webdock_rls.capacity_cluster_allowed(cluster_id) IS NOT TRUE THEN RAISE EXCEPTION 'Cluster authorization required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM webdock_auth.hosting_cluster x WHERE x.id=cluster_snapshot.cluster_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT revoked,last_seen,observation INTO a FROM webdock_auth.hosting_agent x WHERE x.cluster_id=cluster_snapshot.cluster_id FOR SHARE;
 observation_value:=a.observation;
 IF jsonb_typeof(observation_value#>'{capabilities,databasePools}')='array' THEN
  SELECT coalesce(jsonb_agg(value-'allocations'-'observedDatabases'),'[]'::jsonb) INTO pools FROM jsonb_array_elements(observation_value#>'{capabilities,databasePools}');
  observation_value:=jsonb_set(observation_value,'{capabilities,databasePools}',pools);
 END IF;
 RETURN jsonb_build_object('id',c.id,'name',c.name,'ownership',c.ownership,'provider',c.provider,'country',c.country,'region',c.region,
  'locationEvidence',CASE WHEN webdock_rls.operator() THEN c.location_evidence ELSE NULL END,'dedicatedCustomerID',c.dedicated_customer_id,
  'revision',c.revision,'verified',c.verified,'capacity',c.capacity,'verificationEvidence',CASE WHEN webdock_rls.operator() THEN c.verification_evidence ELSE NULL END,
  'revoked',a.revoked,'lastSeen',a.last_seen,'last_seen',a.last_seen,'observation',observation_value);
END $$;


ALTER FUNCTION webdock_rls.cluster_snapshot(cluster_id text) OWNER TO webdock_platform_owner;

--
-- Name: customer_allowed(text, boolean); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.customer_allowed(customer text, writing boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE a jsonb;
BEGIN
 IF webdock_rls.worker(ARRAY['hosting-setup']) THEN RETURN webdock_rls.setup_allowed(customer); END IF;
 IF webdock_rls.worker(ARRAY['database-order']) THEN RETURN customer IS NOT NULL AND webdock_rls.request_scope()->>'customerID'=customer; END IF;
 a:=webdock_rls.actor(); IF a IS NULL THEN RETURN false; END IF;
 IF (a->>'operator')::boolean THEN RETURN true; END IF;
 IF a->'preview'<>'null'::jsonb THEN RETURN NOT writing AND coalesce((a->'preview'->>'valid')::boolean,false) AND a->'preview'->>'customer_id'=customer; END IF;

 IF a ? 'clerk' THEN
  RETURN a->'clerk'->>'customerID'=customer AND a->'clerk'->>'role' IN ('admin','member') AND (NOT writing OR a->'clerk'->>'role'='admin');
 END IF;
 RETURN EXISTS(SELECT 1 FROM webdock_auth.tenant_customer t JOIN webdock_admin.customers c ON c.id=t.customer_id WHERE t.customer_id=customer AND c.status='active' AND webdock_rls.membership_role(t.organization_id) IS NOT NULL AND (NOT writing OR webdock_rls.membership_role(t.organization_id) IN ('owner','admin')));
END $$;


ALTER FUNCTION webdock_rls.customer_allowed(customer text, writing boolean) OWNER TO webdock_policy_owner;

--
-- Name: customer_permission(text, text, boolean); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.customer_permission(customer text, permission text, allow_operator boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE a jsonb; org text; permissions jsonb;
BEGIN
 IF permission NOT IN ('org:projects:manage','org:deployments:create','org:databases:manage','org:billing:manage') THEN RETURN false; END IF;
 a:=webdock_rls.actor(); IF a IS NULL OR a->'preview'<>'null'::jsonb THEN RETURN false; END IF;
 IF allow_operator AND (a->>'operator')::boolean THEN RETURN true; END IF;
 SELECT t.organization_id INTO org FROM webdock_auth.tenant_customer t JOIN webdock_admin.customers c ON c.id=t.customer_id WHERE t.customer_id=customer AND c.status='active';
 IF NOT FOUND OR webdock_rls.membership_role(org) IS NULL THEN RETURN false; END IF;
 IF a ? 'clerk' THEN
  IF a->'clerk'->>'customerID' IS DISTINCT FROM customer OR a->'clerk'->>'organizationID' IS DISTINCT FROM org THEN RETURN false; END IF;
  permissions:=a->'clerk'->'permissions';
 ELSIF webdock_rls.request_scope()->>'authProvider'='clerk' THEN
  SELECT r->'permissions' INTO permissions FROM jsonb_array_elements(webdock_rls.request_scope()->'memberships'->'roles') r WHERE r->>'organizationID'=org AND r->>'customerID'=customer;
 ELSE RETURN webdock_rls.membership_role(org) IN ('owner','admin');
 END IF;
 IF jsonb_typeof(permissions) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(permissions) p WHERE jsonb_typeof(p)<>'string' OR p#>>'{}' NOT IN ('org:projects:manage','org:deployments:create','org:databases:manage','org:billing:manage')) THEN RETURN false; END IF;
 RETURN permissions ? permission;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $$;


ALTER FUNCTION webdock_rls.customer_permission(customer text, permission text, allow_operator boolean) OWNER TO webdock_policy_owner;

