 SELECT EXISTS(SELECT 1 FROM webdock_auth.studio_tenant_preview p
 WHERE p.actor_id=$1 AND p.session_id=$2)
$_$;


ALTER FUNCTION webdock_rls.identity_has_preview(subject text, session_id text) OWNER TO webdock_policy_owner;

--
-- Name: mail_admission_count(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.mail_admission_count(customer text, kind text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF (webdock_rls.customer_allowed(customer) OR webdock_rls.mail_key(customer) OR webdock_rls.worker(ARRAY['mail-cron','mail-send-gateway'])) IS NOT TRUE THEN RAISE EXCEPTION 'Mail admission authorization required' USING ERRCODE='42501'; END IF;
 IF kind='keys' THEN RETURN (SELECT count(*) FROM webdock_auth.mail_api_key WHERE customer_id=customer AND created_at>statement_timestamp()-interval '1 hour'); END IF;
 IF kind='scheduled' THEN RETURN (SELECT count(*) FROM webdock_auth.mail_message WHERE customer_id=customer AND dispatch_status='scheduled'); END IF;
 RAISE EXCEPTION 'Unknown Mail admission count' USING ERRCODE='22023';
END $$;


ALTER FUNCTION webdock_rls.mail_admission_count(customer text, kind text) OWNER TO webdock_platform_owner;

--
-- Name: mail_connection_status(); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.mail_connection_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF webdock_rls.request_scope() IS NULL THEN RAISE EXCEPTION 'Mail authorization required' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('configured',true,'consumerKeySuffix',key_suffix) INTO result FROM webdock_auth.platform_mail_credential WHERE id;
 RETURN coalesce(result,'{"configured":false}'::jsonb);
END $$;


ALTER FUNCTION webdock_rls.mail_connection_status() OWNER TO webdock_platform_owner;

--
-- Name: mail_key(text, text, boolean, boolean); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.mail_key(customer text, connection text DEFAULT NULL::text, writing boolean DEFAULT false, management boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
 SELECT session_user='webdock_auth_runtime' AND webdock_rls.request_scope()->>'kind'='mail-key' AND EXISTS(SELECT 1 FROM webdock_auth.mail_api_key k JOIN webdock_admin.customers c ON c.id=k.customer_id AND c.status='active' JOIN webdock_auth.mail_connection m ON m.id=k.connection_id AND m.customer_id=k.customer_id AND m.deleted_at IS NULL WHERE k.id=webdock_rls.request_scope()->>'keyID' AND k.customer_id=customer AND k.customer_id=webdock_rls.request_scope()->>'customerID' AND k.connection_id=webdock_rls.request_scope()->>'connectionID' AND (connection IS NULL OR k.connection_id=connection) AND k.revoked_at IS NULL AND (NOT management OR k.permission='full_access'))
$$;


ALTER FUNCTION webdock_rls.mail_key(customer text, connection text, writing boolean, management boolean) OWNER TO webdock_policy_owner;

--
-- Name: mail_provider_secret(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.mail_provider_secret(customer text DEFAULT NULL::text, connection text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result text; permitted boolean;
BEGIN
 IF webdock_rls.request_scope()->>'kind'='mail-key' AND (connection IS NULL OR connection IS DISTINCT FROM webdock_rls.request_scope()->>'connectionID') THEN RAISE EXCEPTION 'Mail provider authorization required' USING ERRCODE='42501'; END IF;
 permitted:=webdock_rls.operator();
 IF NOT permitted AND customer IS NOT NULL THEN
  permitted:=(webdock_rls.customer_allowed(customer) AND webdock_rls.actor()->'preview'='null'::jsonb) OR webdock_rls.mail_key(customer,connection) OR webdock_rls.worker(ARRAY['mail-cron','mail-send-gateway']);
  permitted:=coalesce(permitted,false) AND EXISTS(SELECT 1 FROM webdock_auth.mail_tenant_account a WHERE a.customer_id=customer AND a.state='ready' AND a.provider_id IS NOT NULL AND (connection IS NULL OR EXISTS(SELECT 1 FROM webdock_auth.mail_connection c WHERE c.id=connection AND c.customer_id=customer AND c.kind='platform' AND c.provider_account_id=a.provider_id AND c.deleted_at IS NULL)));
 END IF;
 IF permitted IS NOT TRUE THEN RAISE EXCEPTION 'Mail provider authorization required' USING ERRCODE='42501'; END IF;
 SELECT encrypted_secret INTO result FROM webdock_auth.platform_mail_credential WHERE id;
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.mail_provider_secret(customer text, connection text) OWNER TO webdock_platform_owner;

--
-- Name: mail_refresh_domain(text, text, text, jsonb); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.mail_refresh_domain(customer text, connection text, domain_id text, snapshot jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF (webdock_rls.customer_allowed(customer) AND webdock_rls.actor()->'preview'='null'::jsonb OR webdock_rls.mail_key(customer,connection) OR webdock_rls.worker(ARRAY['mail-cron','mail-send-gateway'])) IS NOT TRUE THEN RAISE EXCEPTION 'Mail domain authorization required' USING ERRCODE='42501'; END IF;
 IF webdock_rls.request_scope()->>'kind'='mail-key' AND NOT EXISTS(SELECT 1 FROM webdock_auth.mail_api_key k WHERE k.id=webdock_rls.request_scope()->>'keyID' AND (k.domain_id IS NULL OR k.domain_id=mail_refresh_domain.domain_id)) THEN RAISE EXCEPTION 'Mail domain authorization required' USING ERRCODE='42501'; END IF;
 UPDATE webdock_auth.mail_connection_domain b SET provider_snapshot=snapshot,provider_checked_at=statement_timestamp()
 FROM webdock_auth.mail_sender_domain d,webdock_auth.mail_connection c WHERE b.customer_id=customer AND b.connection_id=connection AND b.domain_id=mail_refresh_domain.domain_id
 AND d.id=b.domain_id AND d.customer_id=customer AND d.deleted_at IS NULL AND d.status='ownership_verified'
 AND c.id=connection AND c.customer_id=customer AND c.deleted_at IS NULL
 AND b.provider_id=snapshot->>'id' AND d.domain=snapshot->>'domain';
 IF NOT FOUND THEN RAISE EXCEPTION 'Mail domain observation changed' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION webdock_rls.mail_refresh_domain(customer text, connection text, domain_id text, snapshot jsonb) OWNER TO webdock_platform_owner;

--
-- Name: mail_usage_total(text, date); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.mail_usage_total(customer text, period date) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE total numeric; native numeric:=0;
BEGIN
 IF (webdock_rls.customer_allowed(customer) OR webdock_rls.mail_key(customer) OR webdock_rls.worker(ARRAY['mail-cron','mail-send-gateway'])) IS NOT TRUE THEN RAISE EXCEPTION 'Mail quota authorization required' USING ERRCODE='42501'; END IF;
 SELECT coalesce(sum(reserved+consumed),0) INTO total FROM webdock_auth.mail_usage_period WHERE customer_id=customer AND mail_usage_period.period=mail_usage_total.period;
 IF to_regclass('webdock_mail.month_usage') IS NOT NULL THEN EXECUTE 'SELECT coalesce(sum(reserved+accepted),0) FROM webdock_mail.month_usage WHERE customer_id=$1 AND period_start=$2' INTO native USING customer,period; END IF;
 RETURN (total+native)::text;
END $_$;


ALTER FUNCTION webdock_rls.mail_usage_total(customer text, period date) OWNER TO webdock_platform_owner;

--
-- Name: membership_role(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.membership_role(org text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE a jsonb; proof jsonb; result text;
BEGIN
 a:=webdock_rls.actor(); IF a IS NULL THEN RETURN NULL; END IF;
 IF a ? 'clerk' THEN RETURN CASE WHEN a->'clerk'->>'organizationID'=org THEN a->'clerk'->>'role' ELSE NULL END; END IF;
 IF webdock_rls.request_scope()->>'authProvider'='clerk' THEN
  proof:=webdock_rls.request_scope()->'memberships';
  IF proof IS NULL OR proof->>'expiresAt' IS NULL OR proof->>'verifiedAt' IS NULL OR (proof->>'expiresAt')::numeric<=extract(epoch FROM statement_timestamp())*1000
   OR (proof->>'verifiedAt')::numeric NOT BETWEEN extract(epoch FROM statement_timestamp())*1000-60000 AND extract(epoch FROM statement_timestamp())*1000
   OR (proof->>'expiresAt')::numeric>(proof->>'verifiedAt')::numeric+60000 THEN RETURN NULL; END IF;
  IF NOT EXISTS(SELECT 1 FROM webdock_auth.clerk_identity i JOIN webdock_auth.clerk_organization o ON o.issuer=i.issuer WHERE i.user_id=a->>'subject' AND i.issuer=proof->>'issuer' AND i.clerk_user_id=proof->>'userID' AND i.enabled AND o.enabled AND o.organization_id=org) THEN RETURN NULL; END IF;
  SELECT r->>'role' INTO result FROM jsonb_array_elements(proof->'roles') r JOIN webdock_auth.tenant_customer t ON t.organization_id=r->>'organizationID' AND t.customer_id=r->>'customerID' WHERE r->>'organizationID'=org AND r->>'role' IN ('admin','member');
  RETURN result;
 END IF;
 SELECT role INTO result FROM webdock_auth.member WHERE "organizationId"=org AND "userId"=a->>'subject';
 RETURN result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN NULL;
END $$;


ALTER FUNCTION webdock_rls.membership_role(org text) OWNER TO webdock_policy_owner;

