CREATE FUNCTION webdock_rls.operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$ SELECT coalesce((webdock_rls.actor()->>'operator')::boolean,false) $$;


ALTER FUNCTION webdock_rls.operator() OWNER TO webdock_policy_owner;

--
-- Name: organization_allowed(text, boolean); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.organization_allowed(org text, writing boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE a jsonb; customer text;
BEGIN
 a:=webdock_rls.actor(); IF a IS NULL THEN RETURN false; END IF;
 IF (a->>'operator')::boolean THEN RETURN true; END IF;
 SELECT customer_id INTO customer FROM webdock_auth.tenant_customer WHERE organization_id=org;
 IF FOUND THEN RETURN webdock_rls.customer_allowed(customer,writing); END IF;
 IF a ? 'clerk' OR webdock_rls.request_scope()->>'authProvider'='clerk' THEN RETURN false; END IF;
 RETURN a->'preview'='null'::jsonb AND EXISTS(SELECT 1 FROM webdock_auth.member m WHERE m."organizationId"=org AND m."userId"=a->>'subject' AND (NOT writing OR m.role IN ('owner','admin')));
END $$;


ALTER FUNCTION webdock_rls.organization_allowed(org text, writing boolean) OWNER TO webdock_policy_owner;

