-- Name: portal_user(); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.portal_user() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
 SELECT CASE WHEN count(*)=1 THEN jsonb_agg(jsonb_build_object('id',u.id,'name',u.name,'email',u.email,'role','operator','authSubject',u.auth_subject,'createdAt',u.created_at,'updatedAt',u.updated_at))->0 ELSE NULL END
 FROM webdock_admin.users u WHERE u.auth_subject=webdock_rls.subject() AND (webdock_rls.request_scope() ? 'clerk' OR webdock_rls.request_scope()->>'authProvider'='clerk' OR u.role='operator') AND coalesce((webdock_rls.actor()->>'root')::boolean,false)
$$;


ALTER FUNCTION webdock_rls.portal_user() OWNER TO webdock_policy_owner;

