--
-- Name: record_vercel_event(text, text, text, boolean, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.record_vercel_event(team text, project text, owner_id text, changed boolean, event text, body_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE receipt record; inserted text; result jsonb;
BEGIN
 IF NOT webdock_rls.worker(ARRAY['vercel-event:'||team||':'||project]) THEN RAISE EXCEPTION 'Event authority required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM webdock_admin.vercel_connection v JOIN webdock_admin.users n ON n.id=v.connected_by JOIN webdock_auth."user" u ON u.id=n.auth_subject WHERE v.team_id=team AND v.connected_by=owner_id AND n.role='operator' AND u.role='operator' AND u."twoFactorEnabled" AND u."emailVerified" AND NOT u."mustChangePassword" AND NOT coalesce(u.banned,false)) THEN RAISE EXCEPTION 'Connection ownership changed' USING ERRCODE='42501'; END IF;
 result:=jsonb_build_object('projectID',project,'region','fra1','changed',changed);
 INSERT INTO webdock_auth.provider_event_receipt(provider,event_id,body_hash,result) VALUES('vercel',event,body_hash,result) ON CONFLICT DO NOTHING RETURNING event_id INTO inserted;
 IF inserted IS NULL THEN
  SELECT * INTO receipt FROM webdock_auth.provider_event_receipt r WHERE r.provider='vercel' AND r.event_id=event;
  IF receipt.body_hash IS DISTINCT FROM body_hash THEN RAISE EXCEPTION 'Conflicting event body' USING ERRCODE='23505'; END IF;
  RETURN receipt.result;
 END IF;
 INSERT INTO webdock_admin.audit_events(id,actor_id,action,target_collection,target_i_d,summary,changed_fields)
 VALUES(webdock_admin.next_snowflake(),owner_id,'update','integrations',project,CASE WHEN changed THEN 'Vercel project region set to fra1; automatic regional failover disabled.' ELSE 'Vercel project region already fra1; automatic regional failover disabled.' END,'resourceConfig');
 RETURN result;
END $$;


ALTER FUNCTION webdock_rls.record_vercel_event(team text, project text, owner_id text, changed boolean, event text, body_hash text) OWNER TO webdock_platform_owner;

--
-- Name: request_scope(); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.request_scope() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $_$
DECLARE raw text; signature text; envelope jsonb; secret_value text; expiry numeric;
BEGIN
 raw:=current_setting('webdock.rls_context',true); signature:=current_setting('webdock.rls_signature',true);
 IF raw IS NULL OR length(raw)>8192 OR signature IS NULL OR signature !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF;
 SELECT secret INTO secret_value FROM webdock_rls.context_key LIMIT 1;
 IF secret_value IS NULL OR length(secret_value)<32 OR encode(webdock_rls.hmac(raw,secret_value,'sha256'),'hex')<>signature THEN RETURN NULL; END IF;
 envelope:=raw::jsonb; expiry:=(envelope->>'exp')::numeric;
 IF envelope->>'v' IS DISTINCT FROM '1' OR envelope->>'aud' IS DISTINCT FROM session_user::text OR session_user NOT IN ('webdock_auth_runtime','webdock_worker_runtime','webdock_registry_runtime') OR expiry IS NULL OR expiry<=extract(epoch FROM statement_timestamp()) OR expiry>extract(epoch FROM statement_timestamp())+120 OR jsonb_typeof(envelope->'scope') IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 RETURN envelope->'scope';
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END $_$;


ALTER FUNCTION webdock_rls.request_scope() OWNER TO webdock_policy_owner;

--
-- Name: retry_billing_read(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.retry_billing_read(job_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE job webdock_auth.billing_job;event webdock_auth.billing_webhook_event;
BEGIN
 IF NOT webdock_rls.operator() THEN RAISE EXCEPTION 'Operator required' USING ERRCODE='42501';END IF;
 -- Keep receipt→job lock ordering consistent with delivery conflict quarantine.
 SELECT * INTO job FROM webdock_auth.billing_job WHERE id=job_id;
 IF NOT FOUND OR job.kind NOT IN ('webhook','reconcile','catalog') OR job.status NOT IN ('failed','needs_review') THEN RAISE EXCEPTION 'Read retry unavailable' USING ERRCODE='55000';END IF;
 IF job.event_id IS NOT NULL THEN
  SELECT * INTO event FROM webdock_auth.billing_webhook_event WHERE id=job.event_id FOR UPDATE;
  IF NOT FOUND OR event.conflict_hash IS NOT NULL OR event.api_version<>'2026-10' OR event.encrypted_body IS NULL THEN RAISE EXCEPTION 'Receipt requires review' USING ERRCODE='55000';END IF;
 END IF;
 SELECT * INTO job FROM webdock_auth.billing_job WHERE id=job_id FOR UPDATE;
 IF job.status NOT IN ('failed','needs_review') THEN RAISE EXCEPTION 'Read retry unavailable' USING ERRCODE='55000';END IF;
 IF job.event_id IS NOT NULL THEN UPDATE webdock_auth.billing_webhook_event SET status='received',processed_at=NULL,error_code=NULL WHERE id=job.event_id;END IF;
 UPDATE webdock_auth.billing_job SET status='pending',attempts=0,available_at=now(),claim_token=NULL,lease_until=NULL,error_code=NULL WHERE id=job_id;
END $$;


ALTER FUNCTION webdock_rls.retry_billing_read(job_id text) OWNER TO webdock_platform_owner;

--
-- Name: revoke_binding_mail_key(text, boolean); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.revoke_binding_mail_key(binding text, retiring boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE b webdock_auth.hosting_service_binding;
BEGIN
 SELECT * INTO b FROM webdock_auth.hosting_service_binding WHERE id=binding FOR UPDATE;
 IF b.id IS NULL OR NOT (webdock_rls.customer_allowed(b.customer_id::text,true) OR webdock_rls.agent_project(b.project_id::text)) THEN RAISE EXCEPTION 'Binding ownership required' USING ERRCODE='42501'; END IF;
 UPDATE webdock_auth.mail_api_key SET revoked_at=coalesce(revoked_at,now()) WHERE customer_id=b.customer_id AND (id=b.retiring_mail_key_id OR (NOT retiring AND id=b.mail_key_id));
 UPDATE webdock_auth.hosting_service_binding SET retiring_mail_key_id=NULL WHERE id=binding;
END $$;


ALTER FUNCTION webdock_rls.revoke_binding_mail_key(binding text, retiring boolean) OWNER TO webdock_platform_owner;

--
-- Name: setup_allowed(text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.setup_allowed(customer text, project text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF NOT webdock_rls.worker(ARRAY['hosting-setup']) THEN RETURN false; END IF;

 IF webdock_rls.request_scope() ? 'clerk' THEN
  RETURN EXISTS(SELECT 1 FROM webdock_auth.hosting_setup s
   JOIN webdock_admin.projects p ON p.id=s.project_id JOIN webdock_admin.customers c ON c.id=s.customer_id
   JOIN webdock_auth.hosting_project h ON h.project_id=p.id JOIN webdock_auth.tenant_customer t ON t.customer_id=c.id
   JOIN webdock_auth.clerk_identity i ON i.user_id=s.actor->>'subject' AND i.issuer=s.actor->'consoleIdentity'->>'issuer' AND i.clerk_user_id=s.actor->'consoleIdentity'->>'userID'
   JOIN webdock_auth."user" u ON u.id=i.user_id
   WHERE s.id=webdock_rls.request_scope()->>'setupID' AND s.generation::text=webdock_rls.request_scope()->>'generation'
   AND s.customer_id=customer AND (project IS NULL OR s.project_id=project) AND s.customer_id=webdock_rls.request_scope()->>'customerID'
   AND s.state='running' AND s.confirmed_preview_id IS NOT NULL AND s.lease_until>now() AND c.status='active' AND p.status='active'
   AND s.actor->'scopes' ? 'hosting:write' AND s.actor->'scopes' ? 'hosting:read' AND i.enabled AND NOT coalesce(u.banned,false)
   AND webdock_rls.request_scope()->'clerk'->>'subject'=u.id AND webdock_rls.request_scope()->'clerk'->>'sessionID'=s.actor->>'sessionID'
   AND webdock_rls.request_scope()->'clerk'->>'issuer'=i.issuer AND webdock_rls.request_scope()->'clerk'->>'userID'=i.clerk_user_id
   AND (webdock_rls.request_scope()->'clerk'->>'expiresAt')::numeric>extract(epoch FROM statement_timestamp())*1000
   AND (webdock_rls.request_scope()->'clerk'->>'verifiedAt')::numeric BETWEEN extract(epoch FROM statement_timestamp())*1000-60000 AND extract(epoch FROM statement_timestamp())*1000
   AND (webdock_rls.request_scope()->'clerk'->>'expiresAt')::numeric<=(webdock_rls.request_scope()->'clerk'->>'verifiedAt')::numeric+60000
   AND jsonb_typeof(webdock_rls.request_scope()->'clerk'->'operator')='boolean'
   AND ((webdock_rls.request_scope()->'clerk'->>'operator')::boolean OR (h.mode='selfservice' AND webdock_rls.request_scope()->'clerk'->>'role' IN ('admin','member') AND jsonb_typeof(webdock_rls.request_scope()->'clerk'->'permissions')='array' AND webdock_rls.request_scope()->'clerk'->'permissions' ? 'org:projects:manage'
    AND (coalesce(s.configuration->'database'->>'mode','none')='none' OR webdock_rls.request_scope()->'clerk'->'permissions' ? 'org:databases:manage')
    AND (coalesce(s.configuration->'source'->>'kind','template')<>'git' OR webdock_rls.request_scope()->'clerk'->'permissions' ? 'org:deployments:create') AND webdock_rls.request_scope()->'clerk'->>'customerID'=customer
    AND EXISTS(SELECT 1 FROM webdock_auth.clerk_organization o WHERE o.issuer=i.issuer AND o.organization_id=t.organization_id AND o.organization_id=webdock_rls.request_scope()->'clerk'->>'organizationID' AND o.enabled AND o.clerk_organization_id=webdock_rls.request_scope()->'clerk'->>'clerkOrganizationID')))
   AND NOT EXISTS(SELECT 1 FROM webdock_auth.console_tenant_preview preview WHERE preview.issuer=i.issuer AND preview.session_id=s.actor->>'sessionID')
   AND NOT EXISTS(SELECT 1 FROM webdock_admin.project_deletion deletion WHERE deletion.project_id=s.project_id AND deletion.status<>'deleted'));
 END IF;
 RETURN EXISTS(
 SELECT 1 FROM webdock_auth.hosting_setup s
 JOIN webdock_admin.projects p ON p.id=s.project_id
 JOIN webdock_admin.customers c ON c.id=s.customer_id
 JOIN webdock_auth.hosting_project h ON h.project_id=p.id
 JOIN webdock_auth.tenant_customer t ON t.customer_id=c.id
 JOIN webdock_auth."user" u ON u.id=s.actor->>'subject'
 JOIN webdock_auth.session session ON session.id=s.actor->>'sessionID' AND session."userId"=u.id
 LEFT JOIN webdock_auth.member m ON m."userId"=u.id AND m."organizationId"=t.organization_id
 WHERE s.id=webdock_rls.request_scope()->>'setupID' AND s.generation::text=webdock_rls.request_scope()->>'generation'
 AND s.customer_id=customer AND (project IS NULL OR s.project_id=project) AND s.customer_id=webdock_rls.request_scope()->>'customerID'
 AND s.state='running' AND s.confirmed_preview_id IS NOT NULL AND s.lease_until>now()
 AND s.actor->'scopes' ? 'hosting:write' AND s.actor->'scopes' ? 'hosting:read'
 AND c.status='active' AND p.status='active' AND session."expiresAt">now()
 AND NOT coalesce(u.banned,false) AND u."emailVerified" AND NOT u."mustChangePassword"
 AND (CASE WHEN webdock_rls.request_scope()->>'authProvider'='clerk' THEN webdock_rls.setup_legacy_permission(customer,'operator') OR (h.mode='selfservice' AND webdock_rls.setup_legacy_permission(customer,'org:projects:manage') AND (coalesce(s.configuration->'database'->>'mode','none')='none' OR webdock_rls.setup_legacy_permission(customer,'org:databases:manage')) AND (coalesce(s.configuration->'source'->>'kind','template')<>'git' OR webdock_rls.setup_legacy_permission(customer,'org:deployments:create'))) ELSE ((u.role='operator' AND u."twoFactorEnabled") OR (u.role='user' AND m.role IN ('owner','admin') AND h.mode='selfservice')) END)
 AND NOT EXISTS(SELECT 1 FROM webdock_auth.studio_tenant_preview preview WHERE preview.session_id=session.id)
 AND NOT EXISTS(SELECT 1 FROM webdock_admin.project_deletion deletion WHERE deletion.project_id=s.project_id AND deletion.status<>'deleted'));
END $$;


ALTER FUNCTION webdock_rls.setup_allowed(customer text, project text) OWNER TO webdock_platform_owner;

--
-- Name: setup_build_capabilities(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.setup_build_capabilities(project text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
BEGIN
 IF NOT webdock_rls.project_allowed(project) THEN RAISE EXCEPTION 'Project access required' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('isolated',EXISTS(SELECT 1 FROM webdock_auth.git_worker WHERE enabled AND isolation='microvm'),'githubActions',EXISTS(SELECT 1 FROM webdock_auth.git_worker WHERE enabled AND isolation='artifact-only'));
END $$;


ALTER FUNCTION webdock_rls.setup_build_capabilities(project text) OWNER TO webdock_platform_owner;

--
-- Name: setup_clerk_revalidation(text, text, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.setup_clerk_revalidation(issuer text, clerk_user text, clerk_session text, clerk_org text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
 SELECT jsonb_build_object(
  'identity',jsonb_build_object('id',u.id,'name',u.name,'email',u.email,'role',u.role,'banned',u.banned,'emailVerified',u."emailVerified",'enabled',i.enabled),
  'organization',CASE WHEN o.organization_id IS NOT NULL THEN jsonb_build_object('id',o.organization_id,'customerID',s.customer_id,'active',c.status='active','enabled',o.enabled) ELSE NULL END)
 FROM webdock_auth.hosting_setup s
 JOIN webdock_admin.customers c ON c.id=s.customer_id
 JOIN webdock_admin.projects p ON p.id=s.project_id AND p.customer_id=s.customer_id
 JOIN webdock_auth.clerk_identity i ON i.issuer=s.actor->'consoleIdentity'->>'issuer' AND i.clerk_user_id=s.actor->'consoleIdentity'->>'userID' AND i.user_id=s.actor->>'subject'
 JOIN webdock_auth."user" u ON u.id=i.user_id
 JOIN webdock_auth.tenant_customer t ON t.customer_id=s.customer_id
 LEFT JOIN webdock_auth.clerk_organization o ON o.issuer=i.issuer AND o.clerk_organization_id=s.actor->'consoleIdentity'->>'organizationID' AND o.organization_id=t.organization_id
 WHERE webdock_rls.worker(ARRAY['hosting-setup-revalidation'])
 AND s.id=webdock_rls.request_scope()->>'setupID' AND s.customer_id=webdock_rls.request_scope()->>'customerID'
 AND s.generation::text=webdock_rls.request_scope()->>'generation'
 AND s.state='running' AND s.confirmed_preview_id IS NOT NULL AND s.lease_until>statement_timestamp()
 AND c.status='active' AND p.status='active'
 AND s.actor->'scopes' ? 'hosting:write' AND s.actor->'scopes' ? 'hosting:read'
 AND i.issuer=setup_clerk_revalidation.issuer AND i.clerk_user_id=clerk_user
 AND s.actor->'consoleIdentity'->>'sessionID'=clerk_session AND s.actor->>'sessionID'=clerk_session
 AND (s.actor->'consoleIdentity'->>'organizationID') IS NOT DISTINCT FROM clerk_org
 AND (clerk_org IS NULL OR o.organization_id IS NOT NULL)
 AND NOT EXISTS(SELECT 1 FROM webdock_admin.project_deletion d WHERE d.project_id=s.project_id AND d.status<>'deleted')
$$;


ALTER FUNCTION webdock_rls.setup_clerk_revalidation(issuer text, clerk_user text, clerk_session text, clerk_org text) OWNER TO webdock_platform_owner;

