--
-- Name: user_visible(text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.user_visible(target text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$ SELECT webdock_rls.operator() OR target=webdock_rls.subject() OR EXISTS(SELECT 1 FROM webdock_auth.member m WHERE m."userId"=target AND webdock_rls.organization_allowed(m."organizationId")) $$;


ALTER FUNCTION webdock_rls.user_visible(target text) OWNER TO webdock_policy_owner;

--
-- Name: vercel_event_access(text, text, text, text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_platform_owner
--

CREATE FUNCTION webdock_rls.vercel_event_access(team text, project text, event text, body_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$
DECLARE receipt record; connection record;
BEGIN
 IF NOT webdock_rls.worker(ARRAY['vercel-event:'||team||':'||project]) THEN RAISE EXCEPTION 'Event authority required' USING ERRCODE='42501'; END IF;
 SELECT * INTO receipt FROM webdock_auth.provider_event_receipt r WHERE r.provider='vercel' AND r.event_id=event;
 IF FOUND THEN
  IF receipt.body_hash IS DISTINCT FROM body_hash THEN RAISE EXCEPTION 'Conflicting event body' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('receipt',receipt.result);
 END IF;
 SELECT v.encrypted_token,v.connected_by INTO connection FROM webdock_admin.vercel_connection v
 JOIN webdock_admin.users n ON n.id=v.connected_by JOIN webdock_auth."user" u ON u.id=n.auth_subject
 WHERE v.team_id=team AND n.role='operator' AND u.role='operator' AND u."twoFactorEnabled" AND u."emailVerified" AND NOT u."mustChangePassword" AND NOT coalesce(u.banned,false);
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('encrypted',connection.encrypted_token,'owner',connection.connected_by);
END $$;


ALTER FUNCTION webdock_rls.vercel_event_access(team text, project text, event text, body_hash text) OWNER TO webdock_platform_owner;

--
-- Name: worker(text[]); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.worker(purposes text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$ SELECT coalesce(session_user='webdock_worker_runtime' AND webdock_rls.request_scope()->>'kind'='system' AND webdock_rls.request_scope()->>'purpose'=ANY(purposes),false) $$;


ALTER FUNCTION webdock_rls.worker(purposes text[]) OWNER TO webdock_policy_owner;

--
-- Name: worker(text[], text); Type: FUNCTION; Schema: webdock_rls; Owner: webdock_policy_owner
--

CREATE FUNCTION webdock_rls.worker(purposes text[], cluster text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'webdock_rls'
    AS $$ SELECT coalesce(cluster IS NOT NULL AND webdock_rls.worker(purposes) AND webdock_rls.request_scope()->>'clusterID'=cluster,false) $$;


ALTER FUNCTION webdock_rls.worker(purposes text[], cluster text) OWNER TO webdock_policy_owner;

