-- Name: clerk_identity webdock_worker_runtime_read; Type: POLICY; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE POLICY webdock_worker_runtime_read ON webdock_auth.clerk_identity FOR SELECT TO webdock_worker_runtime USING ((EXISTS ( SELECT 1
   FROM webdock_mail.identity i
  WHERE ((i.subject = clerk_identity.user_id) AND (webdock_rls.worker(ARRAY['mail-send-gateway'::text, 'mail-webmail-gateway'::text]) OR webdock_rls.agent_customer(i.customer_id))))));


--
-- Name: clerk_identity_mapping webdock_worker_runtime_read; Type: POLICY; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE POLICY webdock_worker_runtime_read ON webdock_auth.clerk_identity_mapping FOR SELECT TO webdock_worker_runtime USING ((webdock_rls.worker(ARRAY['mail-cron'::text, 'mail-send-gateway'::text, 'mail-webmail-gateway'::text, 'git-worker'::text]) OR (webdock_rls.worker(ARRAY['database-order'::text]) AND (local_subject = (webdock_rls.request_scope() ->> 'subject'::text))) OR webdock_rls.setup_identity(local_subject)));


--
-- Name: clerk_organization webdock_worker_runtime_read; Type: POLICY; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE POLICY webdock_worker_runtime_read ON webdock_auth.clerk_organization FOR SELECT TO webdock_worker_runtime USING ((EXISTS ( SELECT 1
   FROM (webdock_auth.tenant_customer t
     JOIN webdock_mail.service s ON ((s.customer_id = (t.customer_id)::text)))
  WHERE ((t.organization_id = clerk_organization.organization_id) AND (webdock_rls.worker(ARRAY['mail-send-gateway'::text, 'mail-webmail-gateway'::text]) OR webdock_rls.agent_customer((t.customer_id)::text))))));


--
-- Name: clerk_session_mapping webdock_worker_runtime_read; Type: POLICY; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE POLICY webdock_worker_runtime_read ON webdock_auth.clerk_session_mapping FOR SELECT TO webdock_worker_runtime USING (((EXISTS ( SELECT 1
   FROM webdock_auth.clerk_identity_mapping m
  WHERE ((m.issuer = clerk_session_mapping.issuer) AND (m.external_subject = clerk_session_mapping.external_subject) AND (m.revoked_at IS NULL) AND ((webdock_rls.worker(ARRAY['git-worker'::text]) AND (EXISTS ( SELECT 1
           FROM webdock_auth.git_release r
          WHERE ((r.approved_by = m.local_subject) AND (r.approved_session_id = clerk_session_mapping.local_session_id) AND (r.status = 'deploying'::text) AND (r.lease_until > now()))))) OR (webdock_rls.worker(ARRAY['database-order'::text]) AND (m.local_subject = (webdock_rls.request_scope() ->> 'subject'::text)) AND (clerk_session_mapping.local_session_id = (webdock_rls.request_scope() ->> 'sessionID'::text))))))) OR (EXISTS ( SELECT 1
   FROM webdock_auth.clerk_identity_mapping m
  WHERE ((m.issuer = clerk_session_mapping.issuer) AND (m.external_subject = clerk_session_mapping.external_subject) AND (m.revoked_at IS NULL) AND webdock_rls.setup_identity(m.local_subject, clerk_session_mapping.local_session_id))))));


--
-- Name: console_tenant_preview webdock_worker_runtime_read; Type: POLICY; Schema: webdock_auth; Owner: webdock_platform_owner
--

CREATE POLICY webdock_worker_runtime_read ON webdock_auth.console_tenant_preview FOR SELECT TO webdock_worker_runtime USING (webdock_rls.worker(ARRAY['database-order'::text, 'agent'::text, 'git-worker'::text, 'mail-cron'::text, 'mail-send-gateway'::text, 'mail-webmail-gateway'::text, 'database-gateway'::text]));


